import{_ as l,o,c as i,a2 as t}from"./chunks/framework.CAKCj7G0.js";const p=JSON.parse('{"title":"Reducer Hook","description":"","frontmatter":{},"headers":[],"relativePath":"DuOneClass/09.react/4-5.扩展Reducer Hook.md","filePath":"DuOneClass/09.react/4-5.扩展Reducer Hook.md"}'),a={name:"DuOneClass/09.react/4-5.扩展Reducer Hook.md"};function r(c,e,d,u,n,s){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="reducer-hook" tabindex="-1">Reducer Hook <a class="header-anchor" href="#reducer-hook" aria-label="Permalink to &quot;Reducer Hook&quot;">​</a></h1><p>Flux：Facebook出品的一个数据流框架</p><ol><li>规定了数据是单向流动的</li><li>数据存储在数据仓库中（目前，可以认为state就是一个存储数据的仓库）</li><li>action是改变数据的唯一原因（本质上就是一个对象，action有两个属性） <ol><li>type：字符串，动作的类型</li><li>payload：任意类型，动作发生后的附加信息</li><li>例如，如果是添加一个学生，action可以描述为： <ol><li><code>{ type:&quot;addStudent&quot;, payload: {学生对象的各种信息} }</code></li></ol></li><li>例如，如果要删除一个学生，action可以描述为： <ol><li><code>{ type:&quot;deleteStudent&quot;, payload: 学生id }</code></li></ol></li></ol></li><li>具体改变数据的是一个函数，该函数叫做reducer <ol><li>该函数接收两个参数 <ol><li>state：表示当前数据仓库中的数据</li><li>action：描述了如何去改变数据，以及改变数据的一些附加信息</li></ol></li><li>该函数必须有一个返回结果，用于表示数据仓库变化之后的数据 <ol><li>Flux要求，对象是不可变的，如果返回对象，必须创建新的对象</li></ol></li><li>reducer必须是纯函数，不能有任何副作用</li></ol></li><li>如果要触发reducer，不可以直接调用，而是应该调用一个辅助函数dispatch <ol><li>该函数仅接收一个参数：action</li><li>该函数会间接去调用reducer，以达到改变数据的目的</li></ol></li></ol>',3)])])}const k=l(a,[["render",r]]);export{p as __pageData,k as default};
